// Cross-engine parity: the app's evaluator must give the same recommendation as the Python engine on every claim
// in the fixture (generated by export_parity_fixture.py). If these disagree, the screen would show a different
// decision from the one the log records.
import { describe, expect, it } from "vitest";
import fixture from "./fixtures/engine_parity.json";
import { evaluate, type Facts } from "@/lib/evaluate";
import type { PolicyRule } from "@/types";

const rulesV1 = fixture.rules_v1 as unknown as PolicyRule[];
const rulesV2 = fixture.rules_v2 as unknown as PolicyRule[];

describe("app evaluator agrees with the engine on the fixture", () => {
  it("v1 recommendations match on every claim", () => {
    const bad = fixture.cases.filter(
      (c) => evaluate(rulesV1, c.facts as Facts).recommendation !== c.expected_v1,
    );
    expect(bad.map((c) => c.case_id)).toEqual([]);
  });

  it("v2 recommendations match on every open claim", () => {
    const open = fixture.cases.filter((c) => c.open);
    const bad = open.filter(
      (c) => evaluate(rulesV2, c.facts as Facts).recommendation !== c.expected_v2,
    );
    expect(bad.map((c) => c.case_id)).toEqual([]);
  });

  it("the fixture covers the expected number of claims", () => {
    expect(fixture.cases.length).toBe(163);
  });
});
